import{_ as n,o as t,c as i,a2 as e}from"./chunks/framework.CqpfiAoK.js";const b=JSON.parse('{"title":"Tabel Umum Pembagian Zaman","description":"","frontmatter":{},"headers":[],"relativePath":"id/70-纪元划分总表.md","filePath":"id/70-纪元划分总表.md","lastUpdated":null}'),d={name:"id/70-纪元划分总表.md"};function m(r,a,s,k,u,l){return t(),i("div",null,[...a[0]||(a[0]=[e('<h1 id="tabel-umum-pembagian-zaman" tabindex="-1">Tabel Umum Pembagian Zaman <a class="header-anchor" href="#tabel-umum-pembagian-zaman" aria-label="Permalink to &quot;Tabel Umum Pembagian Zaman&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Item</th><th>Konten</th></tr></thead><tbody><tr><td>Nomor Dokumen</td><td>70</td></tr><tr><td>Modul</td><td>Zaman Sejarah dan Peristiwa Penting</td></tr><tr><td>Kata Kunci Inti</td><td>Pembagian zaman, periodisasi sejarah, kenaikan dimensi empat tahap, garis waktu, tonggak sejarah</td></tr></tbody></table><h2 id="_1-prinsip-dasar-pembagian-zaman" tabindex="-1">1. Prinsip Dasar Pembagian Zaman <a class="header-anchor" href="#_1-prinsip-dasar-pembagian-zaman" aria-label="Permalink to &quot;1. Prinsip Dasar Pembagian Zaman&quot;">​</a></h2><p>Pembagian zaman sejarah Hengyuanzhou mengambil jalur kenaikan dimensi empat tahap sebagai kerangka dasar, dan keadaan perkembangan mekanisme jangkar sebagai dasar periodisasi inti. Setiap zaman sesuai dengan transformasi mendasar dalam hubungan antara peradaban dan alam semesta; batas antar zaman bukanlah titik waktu sembarang, melainkan ditandai oleh peristiwa penting yang bermakna kosmik.</p><p>Pembagian zaman mengikuti tiga prinsip:</p><ul><li><strong>Prinsip kesesuaian kenaikan dimensi</strong>: setiap zaman besar sesuai dengan satu tahap dalam jalur kenaikan dimensi empat tahap, dan periode subdivisi di dalam zaman sesuai dengan kemajuan kunci dalam tahap tersebut</li><li><strong>Prinsip penandaan peristiwa</strong>: titik awal dan akhir zaman ditentukan oleh peristiwa penting yang menandai, bukan oleh pembagian waktu yang sama sederhana</li><li><strong>Prinsip keadaan peradaban</strong>: setiap zaman dinamai berdasarkan karakteristik inti peradaban pada periode itu, mencerminkan kontradiksi utama dan arah perkembangan pada masa itu</li></ul><h2 id="_2-tabel-umum-zaman-sejarah-hengyuanzhou" tabindex="-1">2. Tabel Umum Zaman Sejarah Hengyuanzhou <a class="header-anchor" href="#_2-tabel-umum-zaman-sejarah-hengyuanzhou" aria-label="Permalink to &quot;2. Tabel Umum Zaman Sejarah Hengyuanzhou&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Nomor Zaman</th><th>Nama Zaman</th><th>Tahap Kenaikan Dimensi yang Sesuai</th><th>Peristiwa Penanda Awal-Akhir</th><th>Karakteristik Inti</th></tr></thead><tbody><tr><td>Zaman Pertama</td><td>Zaman Pra-Jangkar</td><td>Sebelum kenaikan dimensi</td><td>Kelahiran alam semesta→Kebangkitan generasi pertama jangkar</td><td>Kultivasi predator dominan, kegagalan peradaban sering terjadi</td></tr><tr><td>Zaman Kedua</td><td>Zaman Kebangkitan Jangkar</td><td>Awal pembangunan fondasi realitas</td><td>Kebangkitan generasi pertama jangkar→Penandatanganan Piagam Simbiosis</td><td>Mekanisme jangkar didirikan, benih pemikiran anti-predator</td></tr><tr><td>Zaman Ketiga</td><td>Periode Pembentukan Sistem Simbiosis</td><td>Fondasi realitas</td><td>Penandatanganan Piagam Simbiosis→Pembukaan lengkap tiga ratus sistem</td><td>Sistem simbiosis diterapkan, rekonstruksi sosial selesai</td></tr><tr><td>Zaman Keempat</td><td>Zaman Pembukaan dan Aktivasi Sistem</td><td>Awal pemberdayaan teknologi</td><td>Pembukaan tiga ratus sistem→Penyelesaian strategi aktivasi 20%</td><td>Kultivasi dipopulerkan, terobosan dalam teknik rekayasa hukum</td></tr><tr><td>Zaman Kelima</td><td>Zaman Kenaikan Dimensi Pertama</td><td>Pemberdayaan teknologi→Evolusi kesadaran</td><td>Keberhasilan kenaikan dimensi pertama→Pendirian Republik Semua Ras</td><td>Verifikasi kenaikan dimensi peradaban, terobosan antarmuka domain kesadaran</td></tr><tr><td>Zaman Keenam</td><td>Zaman Republik Semua Ras</td><td>Evolusi kesadaran</td><td>Pendirian Republik Semua Ras→Awal eksplorasi antar-bidang</td><td>Penyatuan sistem semua ras, simbiosis kesadaran kolektif</td></tr><tr><td>Zaman Ketujuh</td><td>Zaman Eksplorasi Antar-Bidang</td><td>Evolusi kesadaran→Simbiosis antarbintang</td><td>Awal eksplorasi antar-bidang→Pembangunan awal jaringan antarbintang</td><td>Penemuan besar bidang, perluasan jaringan jangkar</td></tr><tr><td>Zaman Kedelapan</td><td>Zaman Simbiosis Antarbintang</td><td>Simbiosis antarbintang</td><td>Pembangunan jaringan antarbintang→Kenaikan dimensi umum alam semesta</td><td>Simbiosis alam semesta semua ras, kenaikan dimensi alam semesta berlangsung</td></tr></tbody></table><h2 id="_3-rentang-waktu-dan-indikator-kunci-setiap-zaman" tabindex="-1">3. Rentang Waktu dan Indikator Kunci Setiap Zaman <a class="header-anchor" href="#_3-rentang-waktu-dan-indikator-kunci-setiap-zaman" aria-label="Permalink to &quot;3. Rentang Waktu dan Indikator Kunci Setiap Zaman&quot;">​</a></h2><p>Karena Hengyuanzhou mencakup banyak bidang dan kecepatan waktu berbeda antar bidang, rentang waktu zaman didasarkan pada waktu standar bidang utama:</p><table tabindex="0"><thead><tr><th>Zaman</th><th>Rentang Waktu Estimasi</th><th>Tingkat Cakupan Jangkar</th><th>Proporsi Kultivator</th><th>Indeks Tingkat Simbiosis</th></tr></thead><tbody><tr><td>Zaman Pra-Jangkar</td><td>Tidak diketahui (orde miliaran tahun)</td><td>0%</td><td>&lt;0,01%</td><td>&lt;10</td></tr><tr><td>Zaman Kebangkitan Jangkar</td><td>Ribuan tahun</td><td>1%→10%</td><td>0,01%→1%</td><td>10→30</td></tr><tr><td>Periode Pembentukan Sistem Simbiosis</td><td>Berabad-abad</td><td>10%→40%</td><td>1%→10%</td><td>30→50</td></tr><tr><td>Zaman Pembukaan dan Aktivasi Sistem</td><td>Berabad-abad</td><td>40%→70%</td><td>10%→30%</td><td>50→70</td></tr><tr><td>Zaman Kenaikan Dimensi Pertama</td><td>Beberapa dekade</td><td>70%→85%</td><td>30%→50%</td><td>70→80</td></tr><tr><td>Zaman Republik Semua Ras</td><td>Berabad-abad</td><td>85%→95%</td><td>50%→70%</td><td>80→90</td></tr><tr><td>Zaman Eksplorasi Antar-Bidang</td><td>Ribuan tahun</td><td>95%→99%</td><td>70%→90%</td><td>90→95</td></tr><tr><td>Zaman Simbiosis Antarbintang</td><td>Berlangsung</td><td>→100%</td><td>→100%</td><td>→100</td></tr></tbody></table><p>Tingkat cakupan jangkar merujuk pada proporsi sub-wilayah bidang di mana perangkat keras jangkar telah diterapkan; proporsi kultivator merujuk pada proporsi makhluk yang dicakup oleh sistem kultivasi formal; indeks tingkat simbiosis adalah indikator komprehensif yang mengukur tingkat simbiosis peradaban, dengan skor maksimum 100.</p><h2 id="_4-logika-internal-evolusi-zaman" tabindex="-1">4. Logika Internal Evolusi Zaman <a class="header-anchor" href="#_4-logika-internal-evolusi-zaman" aria-label="Permalink to &quot;4. Logika Internal Evolusi Zaman&quot;">​</a></h2><p>Evolusi zaman Hengyuanzhou bukanlah aliran waktu linier, melainkan proses evolusi spiral naik. Setiap zaman menyelesaikan kontradiksi inti yang ditinggalkan oleh zaman sebelumnya, dan pada saat yang sama menciptakan kondisi perkembangan untuk zaman berikutnya:</p><ul><li>Kontradiksi mendasar Zaman Pra-Jangkar adalah kontradiksi antara predasi dan simbiosis, yang ekstrimnya menyebabkan keharusan kebangkitan jangkar</li><li>Zaman Kebangkitan Jangkar menyelesaikan masalah &quot;apakah jangkar ada&quot;, tetapi menghadapi tantangan institusional &quot;untuk siapa jangkar melayani&quot;</li><li>Periode Pembentukan Sistem Simbiosis menyelesaikan konstruksi institusional, tetapi monopoli sumber daya kultivasi masih membatasi evolusi massa</li><li>Zaman Pembukaan dan Aktivasi Sistem memecahkan monopoli kultivasi, tetapi lompatan kemampuan individu membawa tantangan etika dan keamanan baru</li><li>Zaman Kenaikan Dimensi Pertama memverifikasi kelayakan kenaikan dimensi, tetapi kenaikan dimensi satu bidang tidak cukup untuk mendorong evolusi umum alam semesta</li><li>Zaman Republik Semua Ras menyatukan sistem peradaban, tetapi masih ada banyak bidang dan ras yang belum terhubung di alam semesta</li><li>Zaman Eksplorasi Antar-Bidang memperluas batas peradaban, tetapi bidang yang tersebar membutuhkan koneksi antarbintang yang lebih erat</li><li>Zaman Simbiosis Antarbintang akhirnya menunjuk ke tujuan utama kenaikan dimensi umum alam semesta</li></ul><h2 id="_5-penentuan-posisi-zaman-saat-ini" tabindex="-1">5. Penentuan Posisi Zaman Saat Ini <a class="header-anchor" href="#_5-penentuan-posisi-zaman-saat-ini" aria-label="Permalink to &quot;5. Penentuan Posisi Zaman Saat Ini&quot;">​</a></h2><p>Berdasarkan keadaan perkembangan Hengyuanzhou saat ini, peradaban berada pada titik kritis transisi dari Zaman Ketiga (Periode Pembentukan Sistem Simbiosis) ke Zaman Keempat (Zaman Pembukaan dan Aktivasi Sistem). Sistem simbiosis telah diterapkan di bidang-bidang utama, pekerjaan pembukaan tiga ratus sistem berjalan sepenuhnya, dan strategi aktivasi 20% telah memasuki tahap implementasi. Beberapa teknologi inti di lapisan rekayasa hukum (mesin deduksi buah penggandaan, perangkat hukum ruang, sistem cermin salinan) telah berpindah dari laboratorium ke produksi massal.</p><p>Tugas inti periode transisi ini adalah: memastikan pembukaan tiga ratus sistem benar-benar bermanfaat bagi semua makhluk, dan pada saat yang sama membina kelompok pertama makhluk tertinggi bidang melalui strategi aktivasi 20%, mengumpulkan energi dan pengalaman yang cukup untuk kenaikan dimensi pertama.</p><h2 id="penutup" tabindex="-1">Penutup <a class="header-anchor" href="#penutup" aria-label="Permalink to &quot;Penutup&quot;">​</a></h2><p>Tabel Umum Pembagian Zaman adalah kerangka makro untuk memahami evolusi sejarah Hengyuanzhou. Ia merangkum sejarah panjang alam semesta menjadi delapan zaman dengan logika internal yang jelas, masing-masing menjadi tangga yang diperlukan untuk kenaikan dimensi umum alam semesta. Dokumen-dokumen berikutnya akan merinci setiap zaman dan peristiwa penting di dalamnya.</p><h2 id="dokumen-terkait" tabindex="-1">Dokumen Terkait <a class="header-anchor" href="#dokumen-terkait" aria-label="Permalink to &quot;Dokumen Terkait&quot;">​</a></h2><ul><li>71-Zaman Pra-Jangkar</li><li>72-Zaman Kebangkitan Jangkar</li><li>76-Tonggak Kenaikan Dimensi Pertama</li></ul>',22)])])}const g=n(d,[["render",m]]);export{b as __pageData,g as default};
